namespace OpenTPW;

/// <summary>
/// The queue slice's approximation register (docs/GUESTS.md, "Queues"; docs/reverse/QUEUE-plan.md §10). Each
/// entry is tagged <c>[APPROX:QUEUE-NNN]</c> at its code site. Everything else in the queue model is traced
/// from the Mac binary (BIN labels at the code sites).
/// </summary>
public static class QueueApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("QUEUE-003", "guests walk to the join cell, the path cell attached to the back of the queue (the first cardinal neighbour in the order 1, 4, 16, 64 whose bit is set in the back cell's link byte +0x0C, tp.exe 0x4DE840), and join from it; tp.exe's state-10 join (0x4FFBC0) needs the guest's own cell to be the back queue cell (0x4DE110, 0x4DE130), reached through the back cell's link by the walk's edge test 0x4D8750, and uses the attached path cell only for the back cell's fourth place; OpenTPW's ride entrance cell keeps no link byte (ride cells are not typed map cells, WALK-005), so the ride keeps its front in QueueFrontCell where tp.exe reads it from the entrance cell's bit (0x4DE040)"),
		("QUEUE-005", "after a queue edit a guest beyond the new room leaves as tp.exe's 0x501390 sends it, and the others change nothing there (state 11 later re-routes a guest whose place changed through 0x501160) (a guest whose cell left the queue is routed to its new place from where it stands, by the walk search 0x4fa5f0, and leaves only when that fails); a guest sent away thinks Angry by OpenTPW's guest id modulo 3 rather than its thing id (word at thing +0), and its dismissal (0x5012f0) neither records event 6 with the ride id in the guest's event ring (read only by the debug dump 0x4faa60) nor plays the sound for a thing id whose low three bits are 0"),
		("QUEUE-010", "a guest leaving a queue stays on the cell it stood on and decides from there, as tp.exe's queue exit (0x5004aa: unlink 0x4ddd20, dismissal 0x5012f0, state 6) writes no position; a guest leaving from the ride's entrance cell (the stand point of a price refusal or a dismissed head) is placed on the queue's front cell instead, because OpenTPW's untyped ride cells carry no links to walk off by (WALK-005)"),
		("QUEUE-012", "queue cells need allowed terrain, owned land and no object of the queue tool's overwrite priority 3 or more (a lower one is demolished, as tp.exe's validator 0x535670 compares 0x818c10 = 3 with the owner's Info.OverwritePriority); the validator refuses a cell whose flag byte +0x0E has bit 0x40 (the park's land, modelled), allows empty cells and ordinary path cells, and reads no MAP terrain bit (map setup makes inside water, blocked and walkway cells type 0), where OpenTPW's terrain rule also holds the Easymode save's occupied cells"),
		("QUEUE-014", "the queue tool lays straight segments along the dominant axis from the ride's back cell (CellBuildTool, QueueLineWriter), ending on a path cell to connect the queue (code 8 on the last cell), as tp.exe's does (0x536100, ported); tp.exe starts a segment at a cell the player clicks (SetMode 0x52f200 clears the start) and lays anywhere, where the tool starts at the front or back cell; each cell is validated as 0x535670 does (an empty cell is accepted, a path cell is replaced unless NoModify and not on a line's last cell, an object cell of a lower overwrite priority than the queue tool's 3 is demolished and covered by the commit's op 0x87, another ride's queue cell is refused by the owner word +0x10), then typed (0x5346d0), linked, given its queue link toward the previous cell (pass 0x82) and the tool's ride as owner word (pass 0x83, ported); a cell that touches no queue is laid free-standing (no queue link, the ride's owner word only) because the validator never asks a cell to touch the back cell (the remove tool takes it, the ride's chain ignores it); OpenTPW lays no queue over a path cell — evidence needed: the segment commit's first-click handling in 0x524960 (UI-031), the rest of the commit 0x532fc0 and the refund of the cell clear 0x5367a0, which reads the owner word"),
		("QUEUE-015", "the corner walk that the queue tool's entry runs (tp.exe 0x530120) takes a queue that ends on a path cell apart: a walk that steps onto the path cell ends on the queue cell before it and clears the link bit between the two on both cells (0x530379..0x5303A1: 0x522730 on each cell, then the refresh 0x5365d0), so the queue stays unjoined until a line ends on the path again (code 8), where OpenTPW's tool leaves the links alone; the placement counters of the queue cells (+0x20, which the walk sets to 1 on a corner and 0 elsewhere and the clear counts down) are not kept, as the undo takes the cells of the segment outright; the queued guests standing on the cells an undo or a removal takes are set down on the nearest path and dismissed from the queue (GuestSimulation.SetDownOffQueueCells, the exit of the queue-edited re-evaluation 0x501390), where the original's clear writes no guest; the corner stack, the undo by whole segments (Back 0x52fe50) and the demolition's forced clears (0x527ee0) follow the original, and the removal of a queue from a clicked cell on is kept only as the labelled extensions EXT:dev-one-click-remove and EXT:queue-backtrack"),
		("QUEUE-023", "a queue edit of the queue tool (the cell click 0x524960, QueueEdited) opens a closed, connected ride that passes the tests of tp.exe's queue re-evaluation 0x4DE1F0 (not in state 1, 2 or 4, no call +0x64, connection test 0x4DE4A0, a coaster passing 0x441970, a track word +0x2C for karts and water), but the re-evaluation also runs after the placement 0x528A70, 0x52FE50, the cell type setter 0x5346D0 and the cell clear 0x5367A0 (a path edit beside a queue, an object placed or removed), which OpenTPW does not hook, and its opening calls the model routine 0x4547C0 on the type's table entry 0x7A4610, which is not made (evidence needed: what 0x4547C0 does, and whether a placement or a path edit can connect a queue)"),
	};
